// Koalino's logo as a widget (#172): the app icon the navigation rail and About show, so the app
// carries its own icon inside its screens, not only on the launcher and the window frame. The
// picture is ui/assets/branding/koalino.png, generated by branding/make-icons.sh.

import 'package:flutter/material.dart';

/// Finds the logo in widget tests.
const Key koalinoLogoKey = Key('koalino-logo');

/// The logo's asset path, as declared in `pubspec.yaml`.
const String koalinoLogoAsset = 'assets/branding/koalino.png';

/// Koalino's square logo.
final class KoalinoLogo extends StatelessWidget {
  /// Creates the logo [size] logical pixels wide and high.
  ///
  /// Inputs: [size], greater than zero. Output: the logo, with a semantic label so screen readers
  /// name it. Side effects: none (the asset is bundled with the app).
  const KoalinoLogo({super.key = koalinoLogoKey, this.size = 40});

  /// Width and height in logical pixels.
  final double size;

  @override
  Widget build(BuildContext context) => Image.asset(
        koalinoLogoAsset,
        width: size,
        height: size,
        semanticLabel: 'Koalino',
        filterQuality: FilterQuality.medium,
      );
}
